with unpacked as (select id, service, log_ts, level, latency_ms, status_code, context['trace'] as trace, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration as duration_sec, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries as retry_count from app_logs) select level, min(log_ts) as started_at, percentile_approx(status_code, array(0.25, 0.5, 0.75)) as status_code_quartiles, sum(case when level = 'WARN' then duration_sec else 0 end) as warn_duration_sec, count(*) filter (where service = 'search') as search_rows from unpacked group by level order by warn_duration_sec desc;
